// ApproveConversion implements the project-owned lead.approve_conversion Handler.
func ApproveConversion(ctx context.Context, caps capabilities.ApproveConversionCapabilities, input capabilities.ApproveConversionInput) (capabilities.ApproveConversionOutput, error) {
	_ = input
	principal := caps.Execution.Principal()
	lead, err := caps.Lead.GetForUpdate(ctx, caps.Execution.TargetID())
	if err != nil {
		return capabilities.ApproveConversionOutput{}, err
	}
	if lead.Status != schema.LeadStatusQualified {
		return capabilities.ApproveConversionOutput{}, &capabilities.BusinessError{Code: "lead.approve_conversion.precondition_failed", Message: "approval requires a qualified lead"}
	}
	requests, err := caps.ConversionRequest.List(ctx, data.NewConversionRequestQuery().
		WhereLeadEqual(schema.NewConversionRequestLeadReference(lead.ID)).WhereStatusEqual(schema.ConversionRequestStatusPending).Page(1, 200))
	if err != nil {
		return capabilities.ApproveConversionOutput{}, err
	}
	if !hasExactlyOnePendingRequest(requests) {
		return capabilities.ApproveConversionOutput{}, &capabilities.BusinessError{Code: "lead.approve_conversion.pending_request_required", Message: "exactly one pending conversion request is required"}
	}
	request := requests[0]
	completedRequest, err := caps.ConversionRequest.ConditionalUpdate(ctx, data.NewConversionRequestUpdate(request.ID).
		SetStatus(schema.ConversionRequestStatusApproved).RequireStatusEqual(schema.ConversionRequestStatusPending, "lead.approve_conversion.request_conflict").WithExpectedUpdatedAt(request.UpdatedAt))
	if err != nil {
		return capabilities.ApproveConversionOutput{}, err
	}
	updatedLead, err := caps.Lead.ConditionalUpdate(ctx, data.NewLeadUpdate(lead.ID).
		SetStatus(schema.LeadStatusConverted).RequireStatusEqual(schema.LeadStatusQualified, "lead.approve_conversion.lead_conflict").WithExpectedUpdatedAt(lead.UpdatedAt))
	if err != nil {
		return capabilities.ApproveConversionOutput{}, err
	}
	if _, err := caps.Customer.Create(ctx, schema.CreateCustomer{
		CompanyName: lead.CompanyName, ContactName: lead.ContactName,
		ExpectedAmount: schema.CustomerExpectedAmount(lead.ExpectedAmount), SourceLead: schema.NewCustomerSourceLeadReference(lead.ID),
	}); err != nil {
		return capabilities.ApproveConversionOutput{}, err
	}
	if _, err := caps.LeadAudit.Create(ctx, schema.CreateLeadAudit{
		Lead: schema.NewLeadAuditLeadReference(lead.ID), Actor: principal.UserID,
		Operation: schema.LeadAuditOperationConverted, FromStatus: schema.LeadAuditFromStatusQualified,
		ToStatus: schema.LeadAuditToStatusConverted, OccurredAt: time.Now().UTC(),
	}); err != nil {
		return capabilities.ApproveConversionOutput{}, err
	}
	companyName := lead.CompanyName
	now := time.Now().UTC()
	if _, err := caps.Notifications.Dispatch(ctx, capabilities.ApproveConversionNotificationIntent{
		EventType: "lead.conversion_approved", SourceEventID: "conversion_request:" + string(completedRequest.ID) + ":approved",
		RecipientUserIDs: []string{request.RequestedBy}, SubjectObjectKey: "lead", SubjectRecordID: string(lead.ID),
		SubjectVersion: updatedLead.UpdatedAt, DedupeKey: "conversion-approved:" + string(request.ID),
		GroupKey: "lead:" + string(lead.ID), OccurredAt: now,
		Variables: []capabilities.ApproveConversionNotificationVariable{{Key: "company_name", StringValue: &companyName}},
	}); err != nil {
		return capabilities.ApproveConversionOutput{}, err
	}
	return capabilities.ApproveConversionOutput{}, nil
}

func hasExactlyOnePendingRequest(requests []schema.ConversionRequest) bool {
	return len(requests) == 1 && requests[0].Status == schema.ConversionRequestStatusPending
}
