// ConvertDirect implements the project-owned lead.convert_direct Handler.
func ConvertDirect(ctx context.Context, caps capabilities.ConvertDirectCapabilities, input capabilities.ConvertDirectInput) (capabilities.ConvertDirectOutput, error) {
	_ = input
	principal := caps.Execution.Principal()
	lead, err := caps.Lead.GetForUpdate(ctx, caps.Execution.TargetID())
	if err != nil {
		return capabilities.ConvertDirectOutput{}, err
	}
	below, err := amountBelowConversionThreshold(lead.ExpectedAmount)
	if err != nil {
		return capabilities.ConvertDirectOutput{}, err
	}
	if lead.Status != schema.LeadStatusQualified || !below {
		return capabilities.ConvertDirectOutput{}, &capabilities.BusinessError{Code: "lead.convert_direct.precondition_failed", Message: "direct conversion requires a qualified lead below 100000.00"}
	}
	updated, err := caps.Lead.ConditionalUpdate(ctx, data.NewLeadUpdate(lead.ID).
		SetStatus(schema.LeadStatusConverted).RequireStatusEqual(schema.LeadStatusQualified, "lead.convert_direct.status_conflict").WithExpectedUpdatedAt(lead.UpdatedAt))
	if err != nil {
		return capabilities.ConvertDirectOutput{}, err
	}
	if _, err := caps.Customer.Create(ctx, schema.CreateCustomer{
		CompanyName: lead.CompanyName, ContactName: lead.ContactName,
		ExpectedAmount: schema.CustomerExpectedAmount(lead.ExpectedAmount), SourceLead: schema.NewCustomerSourceLeadReference(lead.ID),
	}); err != nil {
		return capabilities.ConvertDirectOutput{}, err
	}
	if _, err := caps.LeadAudit.Create(ctx, schema.CreateLeadAudit{
		Lead: schema.NewLeadAuditLeadReference(lead.ID), Actor: principal.UserID,
		Operation: schema.LeadAuditOperationConverted, FromStatus: schema.LeadAuditFromStatusQualified,
		ToStatus: schema.LeadAuditToStatus(updated.Status), OccurredAt: time.Now().UTC(),
	}); err != nil {
		return capabilities.ConvertDirectOutput{}, err
	}
	return capabilities.ConvertDirectOutput{}, nil
}

func amountBelowConversionThreshold(value schema.LeadExpectedAmount) (bool, error) {
	amount, ok := new(big.Rat).SetString(string(value))
	if !ok {
		return false, &capabilities.BusinessError{Code: "lead.amount.invalid", Message: "expected amount is not an exact decimal"}
	}
	threshold, ok := new(big.Rat).SetString("100000.00")
	if !ok {
		return false, &capabilities.BusinessError{Code: "lead.threshold.invalid", Message: "conversion threshold is invalid"}
	}
	return amount.Cmp(threshold) < 0, nil
}
