// UpdateOwned implements the project-owned lead.update_owned Handler.
func UpdateOwned(ctx context.Context, caps capabilities.UpdateOwnedCapabilities, input capabilities.UpdateOwnedInput) (capabilities.UpdateOwnedOutput, error) {
	principal := caps.Execution.Principal()
	lead, err := caps.Lead.GetForUpdate(ctx, caps.Execution.TargetID())
	if err != nil {
		return capabilities.UpdateOwnedOutput{}, err
	}
	if !leadEditable(lead.Status) {
		return capabilities.UpdateOwnedOutput{}, &capabilities.BusinessError{Code: "lead.update_owned.terminal", Message: "terminal leads are immutable"}
	}
	mutation := data.NewLeadUpdate(lead.ID).WithExpectedUpdatedAt(lead.UpdatedAt).RequireStatusEqual(lead.Status, "lead.update_owned.status_conflict")
	if input.ContactName != nil {
		mutation = mutation.SetContactName(*input.ContactName)
	}
	if input.ContactPhone != nil {
		mutation = mutation.SetContactPhone(*input.ContactPhone)
	}
	if input.ExpectedAmount != nil {
		mutation = mutation.SetExpectedAmount(*input.ExpectedAmount)
	}
	if input.Source != nil {
		mutation = mutation.SetSource(schema.LeadSource(*input.Source))
	}
	updated, err := caps.Lead.ConditionalUpdate(ctx, mutation)
	if err != nil {
		return capabilities.UpdateOwnedOutput{}, err
	}
	detail := "editable lead fields updated"
	if _, err := caps.LeadAudit.Create(ctx, schema.CreateLeadAudit{
		Lead: schema.NewLeadAuditLeadReference(updated.ID), Actor: principal.UserID,
		Operation: schema.LeadAuditOperationUpdated, FromStatus: schema.LeadAuditFromStatus(lead.Status),
		ToStatus: schema.LeadAuditToStatus(updated.Status), Detail: &detail, OccurredAt: time.Now().UTC(),
	}); err != nil {
		return capabilities.UpdateOwnedOutput{}, err
	}
	return capabilities.UpdateOwnedOutput{}, nil
}

func leadEditable(status schema.LeadStatus) bool {
	return status != schema.LeadStatusConverted && status != schema.LeadStatusLost
}
