}

func waitForTask(t *testing.T, client runtimeClient, processID string) workflowTask {
	t.Helper()
	deadline := time.Now().Add(15 * time.Second)
	for time.Now().Before(deadline) {
		response, err := client.request(t.Context(), http.MethodGet, "/workflow/tasks?status=pending&limit=100", nil, runtimeRequestOptions{})
		if err != nil {
			t.Fatal(err)
		}
		if response.Status/100 == 2 {
			tasks, err := decodeWorkflowTasks(response.Body)
			if err != nil {
				t.Fatal(err)
			}
			for _, task := range tasks {
				if processID == "" || task.ProcessID == processID {
					return task
				}
			}
		}
		time.Sleep(100 * time.Millisecond)
	}
	t.Fatalf("pending workflow task not found for process %q", processID)
	return workflowTask{}
}

func decodeJSONMap(t *testing.T, body []byte) map[string]any {
	t.Helper()
	var result map[string]any
	if err := json.Unmarshal(body, &result); err != nil {
		t.Fatalf("decode JSON: %v body=%s", err, body)
	}
	return result
}

func uniqueForPhase(flow string) string {
	return strings.ToLower(flow) + "-stable"
}

func statusValue(record recordEnvelope) string { return fmt.Sprint(record.Data["status"]) }
